sys_script_fix.script:
(function executeFixScript() {
    // Add Destination List (reference to cmdb_ci for example)
    var dict1 = new GlideRecord("sys_dictionary");
    dict1.addQuery("name", "change_request");
    dict1.addQuery("element", "u_destination_list");
    dict1.query();
    if (!dict1.next()) {
        dict1.initialize();
        dict1.name = "change_request";         // table
        dict1.element = "u_destination_list";  // field name
        dict1.internal_type = "reference";     // reference field
        dict1.reference = "u_cisco_secure_access_destination_list";           // reference table (change if needed)
        dict1.column_label = "Destination List";
        dict1.mandatory = false;
        dict1.insert();
    }

    // Add Destination Address (string)
    var dict2 = new GlideRecord("sys_dictionary");
    dict2.addQuery("name", "change_request");
    dict2.addQuery("element", "u_destination_address");
    dict2.query();
    if (!dict2.next()) {
        dict2.initialize();
        dict2.name = "change_request";
        dict2.element = "u_destination_address";
        dict2.internal_type = "string";
        dict2.column_label = "Destination Address";
        dict2.max_length = 200;
        dict2.mandatory = false;
        dict2.insert();
    }
})();
